import { readdirSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { describe, expect, it } from "vitest";

/**
 * Retest finding RX-1. The demo load files are generated by
 * scripts/demo-sql.ts and committed. Migration 0074 refuses a staff claim
 * that has no account, no platform_roles row and no second factor, so a file
 * carrying the old bare claim publishes nothing. These checks keep the
 * committed files, and the database test that runs their prelude
 * (supabase/tests/0077_review_integration.sql), in step with the generator.
 */
const root = resolve(import.meta.dirname, "../../..");
const dir = join(root, "supabase/staging/demo");
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const CLEAR = "select set_config('request.jwt.claims', '', true);";
const claimLines = (sql: string) => sql.split("\n").filter((l) => l.startsWith("select set_config('request.jwt.claims'"));

const test77 = readFileSync(join(root, "supabase/tests/0077_review_integration.sql"), "utf8");
const between = (a: string, b: string) => test77.slice(test77.indexOf(a) + a.length, test77.indexOf(b)).trim();
const prelude = between("-- demo-sql prelude begin", "-- demo-sql prelude end");

describe("the committed demo load files (RX-1)", () => {
  it("has the ten group files and the Maya Vaughn file", () => {
    expect(files).toEqual([...Array.from({ length: 10 }, (_, i) => `group-${i + 1}.sql`).sort(), "mv-live.sql"]);
  });

  it("never sets a staff claim with no account and no second factor", () => {
    for (const f of files) {
      const sql = readFileSync(join(dir, f), "utf8");
      expect(sql, f).not.toContain(`'{"role":"authenticated","app_metadata":{"platform_roles":["owner"]}}'`);
      for (const line of claimLines(sql)) {
        if (line === CLEAR) continue;
        expect(line, f).toContain("from public.platform_roles r where r.role = 'owner'");
        expect(line, f).toContain("'sub', r.user_id");
        expect(line, f).toContain("'aal', 'aal2'");
      }
    }
  });

  it("sets the claims the database test runs, and clears them before the commit", () => {
    expect(prelude.startsWith("select set_config('request.jwt.claims', (select jsonb_build_object(")).toBe(true);
    expect(between("-- demo-sql clear begin", "-- demo-sql clear end")).toBe(CLEAR);
    for (const f of files) {
      const sql = readFileSync(join(dir, f), "utf8");
      const lines = claimLines(sql);
      const sets = lines.filter((l) => l !== CLEAR);
      expect(sets.length, f).toBeGreaterThan(0);
      for (const line of sets) expect(line, f).toBe(prelude);
      // every set is followed by a clear, and the last claims line in the file is a clear
      expect(lines.filter((l) => l === CLEAR).length, f).toBe(sets.length);
      expect(lines[lines.length - 1], f).toBe(CLEAR);
      expect(sql.trimEnd().endsWith("commit;"), f).toBe(true);
    }
  });

  it("says who runs it", () => {
    for (const f of files) expect(readFileSync(join(dir, f), "utf8"), f).toContain("the owner in the SQL editor");
  });
});
